function authView(){root.innerHTML=`<main class="auth"><div class="brand">PS5<span>Library</span></div><h1>${state.register?'A library of your own.':'Make yourself at home.'}</h1><p>${state.register?'Create your personal account on this server.':'Sign in to your private games, downloads and PS5 consoles.'}</p><form id="auth"><label>Username<input name="username" autocomplete="username" required minlength="3"></label><label>Password<input type="password" name="password" autocomplete="${state.register?'new-password':'current-password'}" required minlength="${state.register?12:1}"></label>${state.register?'<label>Invitation code<input name="inviteToken" autocomplete="off"></label><details><summary>First server account</summary><label>Server setup token<input type="password" name="bootstrapToken" autocomplete="off"></label></details>':''}<div id="auth-error" class="error" role="alert"></div><button class="primary">${state.register?'Create account':'Sign in'}</button></form><button class="link" data-action="toggle-auth">${state.register?'Already have an account? Sign in':'Have an invitation? Create an account'}</button><footer>Self-hosted and separate from PlayStation Network.<br>No PSN account or password is needed.</footer></main>`;}
