const downloadPageJobs=()=>state.jobs.filter(job=>job.kind!=='BUILD');
const installedEntry=release=>state.library.find(entry=>entry.releaseId===release?.id&&entry.state==='READY_ON_PS5');
const activeDetailTransfer=()=>state.jobs.find(job=>job.kind==='TRANSFER'&&job.releaseId===state.release?.id&&job.consoleId===state.selectedConsole&&!terminalJob(job));
