const onConsole=g=>g.releases.some(r=>r.kind!=='DLC'&&state.library.some(l=>l.releaseId===r.id&&l.state==='READY_ON_PS5'));
const onServer=g=>g.releases.some(r=>r.kind!=='DLC'&&((r.sources?.length||0)||(r.artifacts?.length||0)));
function catalogGames(){const query=state.query.trim().toLowerCase();return state.catalog.filter(g=>!query||[g.title,g.titleId,g.publisher,...(g.genres||[])].filter(Boolean).join(' ').toLowerCase().includes(query)).filter(g=>state.page==='My library'?onConsole(g):onServer(g));}
function gameCard(g){const selected=g.id===state.selectedGameId,status=state.page==='My library'?'':g.releases.some(r=>r.kind!=='DLC'&&r.artifacts?.length)?'Ready on server':'Source available';return `<button class="library-tile ${selected?'selected':''}" data-preview="${esc(g.id)}" data-game="${esc(g.id)}" aria-pressed="${selected}" aria-controls="library-stage"><span class="library-tile-art"><img loading="lazy" decoding="async" draggable="false" src="${esc(g.coverUrl)}" alt="Cover for ${esc(g.title)}"></span><strong>${esc(g.title)}</strong>${status?`<small>${esc(status)}</small>`:''}</button>`;}
function stageCopyView(g){const release=g.releases.find(r=>r.kind==='UPDATE')||g.releases.find(r=>r.kind==='BASE'),facts=[release?.version&&`Version ${release.version}`,g.platform||'PS5',g.publisher].filter(Boolean);return `<div class="library-stage-copy"><h1 id="library-stage-title">${esc(g.title)}</h1><p>${esc(g.description||'Open the game to review its releases, compatibility, and available actions.')}</p>${facts.length?`<div class="library-facts">${facts.map(value=>`<span>${esc(value)}</span>`).join('')}</div>`:''}<button class="primary library-open" data-game="${esc(g.id)}">Open game</button></div>`;}
