let railDrag=null;const draggedRails=new WeakSet();
function startRailDrag(event){const strip=event.target.closest?.('.library-strip');if(!strip||event.pointerType!=='mouse'||event.button!==0)return;railDrag={strip,pointerId:event.pointerId,startX:event.clientX,startLeft:strip.scrollLeft,moved:false};}
function moveRailDrag(event){if(!railDrag||event.pointerId!==railDrag.pointerId)return;const distance=event.clientX-railDrag.startX;if(!railDrag.moved&&Math.abs(distance)<=5)return;if(!railDrag.moved){railDrag.moved=true;railDrag.strip.setPointerCapture?.(event.pointerId);railDrag.strip.classList.add('dragging');}event.preventDefault();railDrag.strip.scrollLeft=railDrag.startLeft-distance;}
