  <section class="card"><div class="section-head"><div><h2>Redis job queue</h2><p>${esc(queue.name||'Queue diagnostics unavailable')}</p></div><span class="pill ${queue.consumerRunning?'':'offline'}">${queue.consumerRunning?'CONSUMER RUNNING':'CONSUMER OFFLINE'}</span></div><div class="queue-counts">${['active','waiting','delayed','failed','completed','paused'].map(key=>`<div><strong>${esc(queue[key]||0)}</strong><span>${esc(friendly(key))}</span></div>`).join('')}</div></section>
