function drawDetails(){const g=state.game,r=state.release,p=state.plan;if(!g||!r)return;const opening=Date.now()<detailVineUntil,installed=installedEntry(r),transfer=activeDetailTransfer(),console=state.consoles.find(c=>c.id===state.selectedConsole),storage=console?.storage?.find(s=>s.storageId===installed?.storageId),remove=removalButtons(g),manage=g.canManage?'<button data-action="manage-sharing">Manage access</button>':'';setDialog(`<div class="detail-shell"><img class="detail-backdrop" src="${esc(g.heroUrl||g.coverUrl)}" alt=""><div class="detail-shell-shade"></div><button class="close" data-action="close">Close</button><div class="detail-grid"><div class="detail-art-frame"><img class="detail-cover" src="${esc(g.coverUrl)}" alt="Cover for ${esc(g.title)}"></div><svg class="detail-vine" data-animate="${opening}" aria-hidden="true" viewBox="0 0 64 140" focusable="false"><path class="detail-vine-stem" pathLength="1" d="M4 126C50 118 12 38 60 18"/><path class="detail-vine-leaf" pathLength="1" d="M31 82c9-10 18-8 17 3-5 7-11 6-17-3ZM43 52c-8-8-15-4-13 5 5 5 10 3 13-5Z"/></svg><div class="detail-copy"><h1>${esc(g.title)}</h1><p class="detail-description">${esc(g.description||'Description unavailable.')}</p><div class="facts">${esc(g.publisher||'')} · ${esc(g.developer||'')}<br>${esc((g.genres||[]).join(' / '))}</div><div class="detail-selectors"><label>Release<select id="release-select">${releaseOptions(g,r)}</select></label>${consoleSelect('transfer')}</div><section class="transfer-panel">${installed?`<h2>Installed on this PS5</h2><strong>Ready to play</strong><p>${esc(console?.name||'Selected PS5')}${storage?` · ${esc(storage.displayName)}`:''}</p>`:transfer?`<h2>Send to PS5</h2>${detailTransferProgress(transfer)}`:`<h2>Send to PS5</h2><strong>${esc(p?friendly(p.compatibility.status):'Checking compatibility…')}</strong>${p?`<p>${esc(friendly(p.reason))}</p>`:''}${p?.storage.map(s=>`<label class="destination"><span><input type="radio" name="destination" value="${esc(s.storageId)}" ${s.allowed?'':'disabled'}><span>${esc(s.displayName)} · ${bytes(s.freeBytes)} free</span></span><small>${s.allowed?'Enough space available':'Insufficient space or unsupported method'}</small></label>`).join('')||''}${p?.allowed?'<button class="primary" data-action="transfer">Download to this PS5</button>':''}`}</section>${installed?'':`${releaseActions(r)}<p class="detail-cache-note"><small>${r.artifacts.length?'A verified copy is cached on your server and can be reused.':'The server will verify your selected content before publishing it.'}</small></p>`}</div></div>${manage||remove?`<div class="detail-actions">${manage}${remove}</div>`:''}<div class="detail-extras">${trailerPanel(g)}</div></div>`,'[data-action="close"]',true);}
