document.addEventListener('click',event=>{const button=event.target.closest('button');if(button?.dataset.remotePlay){event.preventDefault();showRemotePlay(button.dataset.remotePlay).catch(error=>toast(error.message));}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));try{if(form.id==='auth'){for(const k of ['bootstrapToken','inviteToken'])if(!data[k])delete data[k];const result=await api('/auth/'+(state.register?'register':'login'),'POST',data);state.user=result.user;state.page=location.pathname==='/pair'?'My PS5s':location.pathname==='/profile'?'Profile':'Server library';await refresh();connect();}else if(form.id==='pair'){await api('/pairings/claim','POST',{code:data.code.trim().toUpperCase(),...(data.consoleId?{consoleId:data.consoleId}:{})});toast('PS5Library connected to your account');await refresh();}else if(form.id==='source'){if(data.scanIntervalMinutes==='0')delete data.scanIntervalMinutes;else data.scanIntervalMinutes=Number(data.scanIntervalMinutes);if(!data.tokenEnv)delete data.tokenEnv;if(!data.autoPrepare)delete data.autoPrepare;data.shareCatalog=data.shareCatalog==='on';const s=await api('/sources','POST',data);toast('Scanning your collection…');await api(`/sources/${s.id}/sync`,'POST',{});await refresh();}else if(form.id==='community-request'){await api('/admin/community/request','POST',{displayName:data.displayName});await refresh();toast('Open the authorization link, then wait for Master approval');}else if(form.id==='game-sharing'){const id=state.game.id,userIds=[...form.querySelectorAll('input[name="userId"]:checked')].map(input=>input.value);await api(`/games/${id}/shares`,'PUT',{userIds});await refresh(false);state.game=state.catalog.find(game=>game.id===id);drawDetails();toast('Game access updated');}else if(form.dataset.rename){await api(`/consoles/${form.dataset.rename}`,'PATCH',{name:data.name});await refresh();}}catch(e){const error=document.querySelector('#auth-error');if(form.id==='auth'&&error)error.textContent=e.message;else toast(e.message);}});
document.addEventListener('click',async event=>{if(suppressRailClick(event))return;const b=event.target.closest('button');if(!b)return;try{if(b.dataset.action==='retry-connection'){if(!state.user){location.reload();return;}if(await refresh(false))renderPage();return;}if(b.dataset.removeGame){const c=state.consoles.find(c=>c.id===state.selectedConsole);state.removal={consoleId:c.id,releaseId:b.dataset.removeGame,storageId:b.dataset.storage};setDialog(`<h1>Delete from PS5?</h1><h2>${esc(state.game.title)}</h2><p>${esc(c.name)} · ${esc(c.storage.find(s=>s.storageId===b.dataset.storage)?.displayName||'')}</p><p>Remove this console copy. Your server copy stays available.</p><div class="row"><button class="danger" data-action="confirm-remove">Delete from PS5</button><button data-action="keep-game">Keep game</button></div>`,'[data-action="keep-game"]');}
if(b.dataset.dismissNotice){dismissNotice(b.dataset.dismissNotice);return;}
if(b.dataset.action==='keep-game')drawDetails();
if(b.dataset.action==='confirm-remove'){const r=state.removal;await api(`/consoles/${r.consoleId}/library/remove`,'POST',{releaseId:r.releaseId,storageId:r.storageId,confirm:true});dialog.close();state.page='Downloads';await refresh();toast('Removal queued for your PS5');}
if(b.dataset.backupSave){await api(`/consoles/${b.dataset.backupSave}/saves/backups`,'POST',{localUserId:b.dataset.localUserId,platform:b.dataset.platform,gameTitleId:b.dataset.gameTitle,saveTitleId:b.dataset.saveTitle,directory:b.dataset.directory});await refresh();toast('Save backup requested from your PS5');}
if(b.dataset.deleteSaveBackup)askConfirmation('Delete this save backup?','The encrypted archive will be permanently removed from this server.','Delete backup',async()=>{await api(`/save-backups/${b.dataset.deleteSaveBackup}`,'DELETE');dialog.close();await refresh();toast('Save backup deleted');});
if(b.dataset.action==='confirm-destructive'&&pendingConfirmation){const run=pendingConfirmation;pendingConfirmation=null;await run();}
if(b.dataset.action==='cancel-destructive'){pendingConfirmation=null;dialog.close();}
if(b.dataset.action==='manage-sharing'){const shares=await api(`/games/${state.game.id}/shares`);setDialog(sharingView(shares),'input,button');}if(b.dataset.action==='back-to-game')drawDetails();if(b.dataset.action==='stop-global-sharing'){const id=state.game.id;await api(`/games/${id}/sharing`,'PATCH',{shared:false});await refresh(false);state.game=state.catalog.find(game=>game.id===id);setDialog(sharingView(await api(`/games/${id}/shares`)),'input,button');toast('Server-wide sharing stopped');}if(b.dataset.action==='remove-trailer')askConfirmation('Remove this trailer?','The cached trailer will be removed from this server.','Remove trailer',async()=>{const id=state.game.id;await api(`/games/${id}/trailer`,'DELETE');dialog.close();await refresh(false);state.game=state.catalog.find(g=>g.id===id);drawDetails();toast('Trailer removed');});if(b.dataset.page)await navigate(b.dataset.page);if(b.dataset.profileTab){state.profileTab=b.dataset.profileTab;render();}if(b.dataset.action==='reset-avatar'){await api('/profile/avatar','DELETE',{});await refresh();}if(b.dataset.game)await details(b.dataset.game);if(b.dataset.action==='toggle-auth'){state.register=!state.register;render();}if(b.dataset.action==='close')closeDialog();if(b.dataset.action==='logout'){state.user=null;websocket?.close();await api('/auth/logout','POST',{});Object.assign(state,{catalog:[],consoles:[],jobs:[],sources:[],artifacts:[],selectedConsole:'',selectedGameId:'',game:null,profile:null});dialog.close();render();}if(b.dataset.action==='invite'){const i=await api('/admin/invites','POST',{});document.querySelector('#invite-result').innerHTML=`<p>Single use · expires in 7 days</p><label>Invitation code<input readonly value="${esc(i.token)}"></label>`;}if(b.dataset.sync){await api(`/sources/${b.dataset.sync}/sync`,'POST',{});await refresh();toast('Collection scanned');}if(b.dataset.default){await api(`/consoles/${b.dataset.default}`,'PATCH',{isDefault:true});state.selectedConsole=b.dataset.default;await refresh();}if(b.dataset.refreshConsole){await api(`/consoles/${b.dataset.refreshConsole}/refresh`,'POST',{});toast('Firmware refresh requested for the next console connection');}if(b.dataset.testNotification){await api(`/consoles/${b.dataset.testNotification}/notifications/test`,'POST',{});toast('Notification queued for your PS5');}if(b.dataset.revoke)askConfirmation('Revoke this console?','This PS5 will lose access and must be paired again.','Revoke access',async()=>{await api(`/consoles/${b.dataset.revoke}/revoke`,'POST',{});dialog.close();await refresh();toast('Device credential revoked');});if(b.dataset.forgetConsole)askConfirmation('Remove this console record?','This deletes its saved identity, jobs, console library state and recovery key. The PS5 must be registered again.','Remove console',async()=>{await api(`/admin/consoles/${b.dataset.forgetConsole}`,'DELETE');dialog.close();state.selectedConsole='';await refresh();toast('Console record removed');});if(b.dataset.delete)askConfirmation('Delete this cached package?','The verified server copy will be removed. Original source files and PS5 installs stay available.','Delete cached copy',async()=>{const result=await api(`/artifacts/${b.dataset.delete}`,'DELETE');dialog.close();await refresh();toast(`${bytes(result.freedBytes)} removed from the server cache`);});if(b.dataset.dismissJob){await api(`/jobs/${b.dataset.dismissJob}`,'DELETE');await refresh();toast('Download history dismissed');}if(b.dataset.control){await api(`/jobs/${b.dataset.control}/control`,'POST',{action:b.dataset.command});await refresh();}if(b.dataset.prepare){b.disabled=true;b.setAttribute('aria-busy','true');const result=await api('/preparations','POST',{sourceReleaseId:b.dataset.sourceRelease,method:b.dataset.prepare});dialog.close();state.page=result.cached?'Server cache':'Preparing';await refresh();toast(result.cached?'Reusing your verified cached package':'Preparation queued');}if(b.dataset.action==='download'){b.disabled=true;b.setAttribute('aria-busy','true');await api('/downloads','POST',{sourceReleaseId:b.dataset.sourceRelease});dialog.close();state.page='Downloads';await refresh();}if(b.dataset.action==='transfer'){const plan=state.plan;if(!plan||!plan.artifactId||plan.releaseId!==state.release?.id||plan.consoleId!==state.selectedConsole)throw Error('Transfer plan is no longer current');const selected=dialog.querySelector('input[name="destination"]:checked');if(!selected)throw Error('Select a storage destination');const queued=await api('/transfers','POST',{artifactId:plan.artifactId,consoleId:plan.consoleId,storageId:selected.value});if(!state.jobs.some(job=>job.id===queued.id))state.jobs.unshift({id:queued.id,kind:'TRANSFER',releaseId:plan.releaseId,consoleId:plan.consoleId,storageId:selected.value,state:'QUEUED_FOR_PS5',downloadedBytes:0,totalBytes:null});drawDetails();while(refreshing)await new Promise(resolve=>setTimeout(resolve,25));await refresh(false);drawDetails();toast('Download queued for your PS5');}}catch(e){b.disabled=false;b.removeAttribute('aria-busy');reportError(e);}});
document.addEventListener('change',async event=>{try{if(event.target.id==='trailer-upload'){const file=event.target.files?.[0];if(file)await uploadTrailer(file);}if(event.target.id==='profile-picture'){const file=event.target.files?.[0];if(!file)return;if(file.size>4*1024**2)throw Error('Choose an image smaller than 4 MB');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});await api('/profile/avatar','POST',{data});await refresh();toast('Account picture updated');}if(event.target.dataset.consoleSelect){state.selectedConsole=event.target.value;if(dialog.open){state.library=state.selectedConsole?await api(`/consoles/${state.selectedConsole}/library`):[];await updatePlan();}else await refresh();}if(event.target.id==='release-select'){state.release=state.game.releases.find(r=>r.id===event.target.value);await updatePlan();}}catch(e){toast(e.message);}});
document.addEventListener('input',event=>{if(event.target.id==='search'){state.query=event.target.value;const view=document.querySelector('#catalog-view');if(view)view.outerHTML=catalogView();}});
document.addEventListener('click',event=>{const button=event.target.closest('button');if(button?.dataset.action==='refresh-manager')refresh().catch(error=>toast(error.message));});
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.restartService){const service=button.dataset.restartService;setDialog(`<h1>Restart ${esc(friendly(service))}?</h1><p>Active work using this service may pause briefly. Docker will keep its persistent data and restart the same container.</p><div class="row"><button class="danger" data-confirm-restart="${esc(service)}">Restart service</button><button data-action="cancel-admin-action">Cancel</button></div>`,'[data-action="cancel-admin-action"]');}
  if(button.dataset.confirmRestart){const service=button.dataset.confirmRestart;await api(`/admin/services/${service}/restart`,'POST',{confirm:service});dialog.close();toast(`${friendly(service)} restart requested`);setTimeout(()=>refresh().catch(()=>{}),4000);}
  if(button.dataset.action==='clear-logs'){setDialog('<h1>Clear dashboard logs?</h1><p>This removes the current rotated application log files. Service data and audit records stored in the database are not changed.</p><div class="row"><button class="danger" data-action="confirm-clear-logs">Clear logs</button><button data-action="cancel-admin-action">Cancel</button></div>','[data-action="cancel-admin-action"]');}
  if(button.dataset.action==='confirm-clear-logs'){await api('/admin/logs','DELETE');dialog.close();await refresh();toast('Application logs cleared');}
  if(button.dataset.action==='cancel-admin-action')dialog.close();
}catch(error){toast(error.message);}});
document.addEventListener('change',event=>{if(event.target.id==='manager-service'){state.logService=event.target.value;refresh().catch(error=>toast(error.message));}if(event.target.id==='manager-level'){state.logLevel=event.target.value;refresh().catch(error=>toast(error.message));}});
document.addEventListener('click',async event=>{const action=event.target.closest('button')?.dataset.action;if(!['refresh-community','disconnect-community'].includes(action))return;try{if(action==='refresh-community'){await api('/admin/community/refresh','POST',{});await refresh();toast('Community status refreshed');}if(action==='disconnect-community')askConfirmation('Disconnect Community Master?','Community saves, friends and groups will stop synchronizing until you connect again.','Disconnect',async()=>{await api('/admin/community','DELETE');dialog.close();await refresh();toast('Community disconnected');});}catch(error){toast(error.message);}});
dialog.addEventListener('click',closeDialogFromBackdrop);
dialog.addEventListener('cancel',event=>{if(dialog.querySelector('.detail-grid')){event.preventDefault();closeDialog();}});
dialog.addEventListener('close',()=>{pendingConfirmation=null;dialog.classList.remove('closing');});
setInterval(async()=>{if(state.user&&state.page==='Profile'&&state.profileTab==='saves'&&!refreshing)try{state.saveBackups=await api('/save-backups');const selected=(state.profile?.consoles||[]).find(console=>console.id===state.selectedConsole)||(state.profile?.consoles||[])[0],view=document.querySelector('#save-backups-view');if(view&&!view.contains(document.activeElement))view.outerHTML=saveBackupsView(selected);}catch(error){toast(error.message);}},5000);
setInterval(()=>{if(state.user&&dialog.open&&state.game?.trailerState&&['QUEUED','PREPARING'].includes(state.game.trailerState)){const id=state.game.id;refresh(false).then(()=>{if(dialog.open&&state.game?.id===id){state.game=state.catalog.find(g=>g.id===id);const panel=document.querySelector('#trailer-panel');if(panel)panel.outerHTML=trailerPanel(state.game);}}).catch(()=>{});}if(state.user&&!dialog.open&&!root.contains(document.activeElement)&&['My library','Server library','Downloads','Preparing','Server cache'].includes(state.page))refresh(false).then(updated=>{if(updated)renderPage();}).catch(()=>{});},30000);
(async()=>{try{state.user=await api('/me');}catch(error){if(error.status===401)authView();else offlineView();return;}state.page=location.pathname==='/pair'?'My PS5s':location.pathname==='/profile'?'Profile':'Server library';try{await refresh();}catch{render();}connect();})();
